import { line } from 'axylo';

/**
 * Draws the daily signups from data.json as a line chart.
 *
 * Rows look like { day: '2026-04-06', signpus: 207 }. The value key is spelled
 * `signpus` in the source data, so the field is named exactly that, and the
 * label gives readers the proper word in the axis title, tooltip and table.
 *
 * @param {HTMLElement} element the chart container
 * @param {ReadonlyArray<{ day: string, signpus: number | null }>} data rows from data.json
 * @returns the Axylo chart handle
 */
export default function render(element, data) {
  return line(element, {
    title: 'Daily signups',
    data,
    // 'YYYY-MM-DD' strings are calendar days: the same date in every time zone.
    x: { field: 'day', type: 'date' },
    y: { field: 'signpus', label: 'Signups' },
  });
}

