input.command:
node --input-type=module -e "
import { validate } from 'axylo';
import { readFileSync } from 'node:fs';
const data = JSON.parse(readFileSync('data.json', 'utf8'));
const problems = validate('line', { title: 'Daily signups', data, x: { field: 'day', type: 'date' }, y: { field: 'signpus', label: 'Signups' } });
console.log(problems.length, 'diagnostics');
for (const d of problems) console.log(d.code, d.level, d.message);
"

